previewCss:
.darma-loader-darma-b15-javelin-arc { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #bbf7d0); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .66); position: relative; }
.darma-loader-darma-b15-javelin-arc .darma-loader-darma-b15-javelin-arc__field { position: absolute; left: 0; right: 0; bottom: 10%; height: 6%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 35%, transparent); }
.darma-loader-darma-b15-javelin-arc i { position: absolute; bottom: 17%; width: 2%; height: 8%; border-radius: 2px; background: color-mix(in srgb, var(--accent) 50%, transparent); }
.darma-loader-darma-b15-javelin-arc i:nth-of-type(1) { left: 34%; }
.darma-loader-darma-b15-javelin-arc i:nth-of-type(2) { left: 58%; }
.darma-loader-darma-b15-javelin-arc i:nth-of-type(3) { left: 82%; }
.darma-loader-darma-b15-javelin-arc .darma-loader-darma-b15-javelin-arc__spear { position: absolute; left: 4%; bottom: 22%; width: 34%; height: 4%; border-radius: 2px; background: linear-gradient(90deg, var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-javelin-arc-jav-throw calc(var(--loader-speed, 1s) * 2.2) cubic-bezier(.35, .05, .55, 1) infinite; }
@keyframes darma-loader-darma-b15-javelin-arc-jav-throw { 0% { opacity: 0; transform: translate(0, 0) rotate(-32deg); } 10% { opacity: 1; } 50% { transform: translate(96%, -170%) rotate(-4deg); } 88% { opacity: 1; transform: translate(190%, 4%) rotate(54deg); } 100% { opacity: 0; transform: translate(190%, 4%) rotate(54deg); } }

